import { defineNuxtPlugin } from '#imports'
// Virtual module generated by this module's own `setup()` (see `addTypeTemplate` in
// `module.ts`) - only resolvable once consumed inside a real Nuxt app build, hence the
// `eslint-disable`/`ts-ignore` pair instead of `@ts-expect-error` (which would itself be
// flagged as unused once the ambient declaration is generated).
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import files from '#navigation/files'
import { pushNavigationItems, resetNavigationGroups } from '../utils/state'
import type { NavigationFile } from '../../../types'

/**
 * Runs every registered module's navigation file once per app instance (server: once per
 * request, client: once on hydration), populating the shared navigation state consumed by
 * `useNavigation`. Resets the state first so repeated runs within the same server process (e.g.
 * concurrent requests) don't accumulate duplicate items.
 *
 * `onClick` handlers are only ever meaningful once attached to a real DOM event on the client -
 * rendering a tile's `title`/`description`/`to` works the same during SSR.
 */
export default defineNuxtPlugin({
  name: 'frigear-nu:navigation',
  async setup() {
    resetNavigationGroups()

    for (const file of files as NavigationFile[]) {
      const items: Parameters<NavigationFile>[0] = []
      await file(items)
      if (items.length > 0) pushNavigationItems('', items)
    }
  },
})
